<template>
  <div class="page">
    <div class="panel">
      <h1>JW Player 8.0.12 + Vue 2</h1>
      <p class="desc">
        页面通过 <code>script</code> 标签加载 JW Player，默认播放
        <code>{{ defaultSource }}</code>。
      </p>

      <label class="label" for="hlsUrl">HLS 地址</label>
      <div class="toolbar">
        <input id="hlsUrl" v-model.trim="source" class="input" type="text" />
        <button class="button" type="button" @click="reloadPlayer">重新加载</button>
        <button class="button button-close" type="button" @click="openExitModal">
          关闭播放
        </button>
      </div>

      <div v-if="!isPlayerClosed" id="jwplayer-demo"></div>
      <div v-else class="player-closed">
        已退出播放，点击“重新加载”可重新创建播放器。
      </div>

      <div class="meta">
        <div><strong>发布编号：</strong><code>{{ buildId }}</code></div>
        <div><strong>本地示例文件：</strong><code>public/sample.m3u8</code></div>
        <div>
          <strong>当前播放地址：</strong><code>{{ source }}</code>
        </div>
      </div>
    </div>

      <div v-if="isExitModalVisible" class="modal-mask">
        <div class="modal" role="dialog" aria-modal="true" aria-labelledby="exit-modal-title">
          <h2 id="exit-modal-title">是否要退出播放？</h2>
          <p>弹出确认框时会先暂停播放器，继续观看后会恢复播放。</p>
          <p v-if="isVideoHiddenForModal" class="modal-tip">
            检测到弹窗可能被视频层遮挡，已临时隐藏 video 标签。
          </p>
          <div class="modal-actions">
            <button class="button button-secondary" type="button" @click="continueWatching">
              继续观看
          </button>
          <button class="button button-close" type="button" @click="exitWatching">
            退出观看
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
const defaultSource = `${process.env.BASE_URL}sample.m3u8`;
const buildId = process.env.VUE_APP_BUILD_ID || "dev-build";

export default {
  name: "App",
  data() {
    return {
      buildId,
      defaultSource,
      source: defaultSource,
      isExitModalVisible: false,
      isPlayerClosed: false,
      shouldResumeAfterModal: false,
      isVideoHiddenForModal: false,
    };
  },
  mounted() {
    this.setupPlayer();
  },
  beforeDestroy() {
    if (window.jwplayer) {
      window.jwplayer("jwplayer-demo").remove();
    }
  },
  methods: {
    getPlayer() {
      return window.jwplayer ? window.jwplayer("jwplayer-demo") : null;
    },
    getPlayerVideos() {
      return Array.from(document.querySelectorAll("#jwplayer-demo video"));
    },
    hidePlayerVideos() {
      this.getPlayerVideos().forEach((video, index) => {
        if (!video.dataset.originalDisplay) {
          video.dataset.originalDisplay = video.style.display || "";
        }
        video.dataset.hiddenForModal = "true";
        video.style.display = "none";
        video.setAttribute("data-hidden-video-index", String(index));
      });
      this.isVideoHiddenForModal = true;
    },
    restorePlayerVideos() {
      this.getPlayerVideos().forEach((video) => {
        if (video.dataset.hiddenForModal === "true") {
          video.style.display = video.dataset.originalDisplay || "";
          delete video.dataset.hiddenForModal;
          delete video.dataset.originalDisplay;
          video.removeAttribute("data-hidden-video-index");
        }
      });
      this.isVideoHiddenForModal = false;
    },
    modalSeemsCovered() {
      const modal = document.querySelector(".modal");
      if (!modal) {
        return false;
      }

      const rect = modal.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;
      const topElement = document.elementFromPoint(centerX, centerY);

      return Boolean(topElement) && !modal.contains(topElement);
    },
    detectAndHideCoveredVideo() {
      window.requestAnimationFrame(() => {
        window.requestAnimationFrame(() => {
          if (this.isExitModalVisible && this.modalSeemsCovered()) {
            this.hidePlayerVideos();
          }
        });
      });
    },
    setupPlayer() {
      if (!window.jwplayer) {
        throw new Error("JW Player script failed to load.");
      }

      this.getPlayer().setup({
        file: this.source,
        width: "100%",
        aspectratio: "16:9",
        image: "https://dummyimage.com/1280x720/0f172a/ffffff&text=JW+Player+HLS+Demo",
        title: "Sample HLS Stream",
        autostart: false,
        mute: false,
      });
    },
    reloadPlayer() {
      const player = this.getPlayer();
      if (player && !this.isPlayerClosed) {
        player.remove();
      }

      this.restorePlayerVideos();
      this.isExitModalVisible = false;
      this.isPlayerClosed = false;
      this.$nextTick(() => {
        this.setupPlayer();
      });
    },
    openExitModal() {
      const player = this.getPlayer();
      if (player) {
        this.shouldResumeAfterModal = player.getState() === "playing";
        player.pause(true);
      }

      this.isExitModalVisible = true;
      this.detectAndHideCoveredVideo();
    },
    continueWatching() {
      this.isExitModalVisible = false;
      this.restorePlayerVideos();
      const player = this.getPlayer();
      if (player && this.shouldResumeAfterModal) {
        player.play(true);
      }
      this.shouldResumeAfterModal = false;
    },
    exitWatching() {
      const player = this.getPlayer();
      if (player) {
        player.remove();
      }

      this.isExitModalVisible = false;
      this.isPlayerClosed = true;
      this.shouldResumeAfterModal = false;
      this.restorePlayerVideos();
    },
  },
};
</script>

<style scoped>
.page {
  min-height: 100vh;
  padding: 40px 20px;
  background: #f8fafc;
  color: #0f172a;
  font-family: Arial, Helvetica, sans-serif;
}

.panel {
  max-width: 960px;
  margin: 0 auto;
  background: #ffffff;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
}

h1 {
  margin: 0 0 12px;
  font-size: 28px;
}

.desc {
  margin: 0 0 20px;
  line-height: 1.6;
}

.label {
  display: block;
  margin-bottom: 8px;
  font-weight: 700;
}

.toolbar {
  display: flex;
  gap: 12px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 10px;
  font-size: 14px;
}

.button {
  border: 0;
  border-radius: 10px;
  padding: 12px 18px;
  background: #2563eb;
  color: #ffffff;
  font-size: 14px;
  cursor: pointer;
}

.button-close {
  background: #dc2626;
}

.button-secondary {
  background: #475569;
}

.player-closed {
  display: grid;
  place-items: center;
  min-height: 280px;
  margin-top: 8px;
  border: 1px dashed #94a3b8;
  border-radius: 12px;
  background: #f8fafc;
  color: #475569;
  text-align: center;
  padding: 24px;
}

.meta {
  margin-top: 20px;
  display: grid;
  gap: 8px;
  line-height: 1.6;
}

.modal-mask {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(15, 23, 42, 0.55);
}

.modal {
  width: min(100%, 420px);
  background: #ffffff;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.2);
}

.modal h2 {
  margin: 0 0 12px;
  font-size: 22px;
}

.modal p {
  margin: 0 0 20px;
  color: #475569;
  line-height: 1.6;
}

.modal-tip {
  margin-top: -8px;
  color: #b45309;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

code {
  background: #e2e8f0;
  border-radius: 6px;
  padding: 2px 6px;
}
</style>
